CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `pontok`  AS   (select `pontaranyegyt`.`Points` AS `Points` from `pontaranyegyt` order by `pontaranyegyt`.`Szazalek` desc)  ;
